/**
 * BORA Engine — Phase 17.15: long deterministic stress
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * Long runs over DETERMINISTIC repeating patterns. No randomness: every event
 * is generated by fixed arithmetic, so a failure is always reproducible by
 * reading the pattern rather than by replaying a generator seed.
 *
 * The purpose is to expose accumulation, numerical drift, unbounded state
 * growth, or state retention problems — NOT to measure performance.
 */

import { describe, it, expect } from 'vitest';
import { runSimulation, fingerprintText, scenarioJLongRun } from '../index';
import type { SimulationEvent } from '../scenario';
import type { RolloverSong } from '../../engine/rollover/rollover';
import type { HourIndex } from '../../engine/types';

const H = 30000 as HourIndex;
const hour = (n: number) => n as HourIndex;

function song(id: string, over: Partial<RolloverSong> = {}): RolloverSong {
  return {
    songId: id,
    lifecycle: 'ACTIVE',
    k: 0,
    persistentKura: 0,
    buckets: [],
    seedHours: [],
    platform: { youtube: [], spotify: [], boomplay: [] },
    ...over,
  };
}

/**
 * A fixed 8-hour cycle of activity across four songs.
 *
 * The pattern is arithmetic, not random: `h % 8` selects a repeating profile,
 * so any hour can be reasoned about directly.
 */
function buildEvents(hours: number): SimulationEvent[] {
  const events: SimulationEvent[] = [];

  for (let h = H; h < H + hours; h++) {
    const phase = h % 8;

    // ALPHA: always busy, high volume on even phases.
    events.push({
      kind: 'BUCKET', songId: 'ALPHA', hour: hour(h),
      upvotes: phase % 2 === 0 ? 5 : 1, downvotes: 0,
    });

    // BETA: half the volume, sometimes downvoted.
    events.push({
      kind: 'BUCKET', songId: 'BETA', hour: hour(h),
      upvotes: phase < 4 ? 1 : 0, downvotes: phase < 4 ? 0 : 1,
    });

    // GAMMA: idle for a quarter of every cycle.
    if (phase !== 7) {
      events.push({
        kind: 'BUCKET', songId: 'GAMMA', hour: hour(h), upvotes: 5, downvotes: 0,
      });
    }

    // DELTA: a single zero-vote bucket, exercising the C=0 path at scale.
    events.push({
      kind: 'BUCKET', songId: 'DELTA', hour: hour(h), upvotes: 0, downvotes: 0,
    });

    // Platform activity drifts with the phase on a bounded range.
    events.push({
      kind: 'PLATFORM', songId: 'ALPHA', hour: hour(h), platform: 'youtube', value: phase * 10,
    });
    events.push({
      kind: 'PLATFORM', songId: 'BETA', hour: hour(h), platform: 'spotify', value: (7 - phase) * 5,
    });
  }

  // Lifecycle churn on fixed hour offsets.
  events.push({ kind: 'VAULT', songId: 'DELTA', hour: hour(H + 100) });
  events.push({ kind: 'RESTORE', songId: 'DELTA', hour: hour(H + 400) });
  events.push({ kind: 'VAULT', songId: 'BETA', hour: hour(H + 900) });

  return events;
}

function longRun(hours: number) {
  return runSimulation({
    name: `stress-${hours}`,
    initialState: {
      referenceHour: H,
      songs: [
        song('ALPHA', { k: 100, persistentKura: 20 }),
        song('BETA', { k: 50, persistentKura: 10 }),
        song('GAMMA', { k: 25 }),
        song('DELTA', { k: 7, persistentKura: 5 }),
      ],
    },
    hours,
    events: buildEvents(hours),
  });
}

describe('A-17.15: long deterministic stress', () => {
  /**
   * Multi-thousand-hour runs legitimately take much longer than the default 5s
   * budget, and the 10 000-hour case is heavy enough that it needs a generous
   * budget to survive running alongside the rest of the suite.
   *
   * Timeouts are raised PER TEST rather than globally, so no other suite is
   * affected and a genuine hang still fails loudly rather than hanging CI.
   */
  const LONG = 120_000;
  const VERY_LONG = 600_000;

  for (const hours of [1000, 5000]) {
    it(`completes ${hours} hours, every hour advanced, no violation`, { timeout: LONG }, () => {
      const r = longRun(hours);
      expect(r.ok).toBe(true);
      if (!r.ok) return;

      expect(r.value.snapshots).toHaveLength(hours);
      expect(r.value.metrics.hoursSimulated).toBe(hours);

      // Every hour advanced by exactly one, contiguously from the start.
      for (let i = 0; i < hours; i++) {
        expect(r.value.snapshots[i].hour).toBe(H + i);
        expect(r.value.snapshots[i].nextHour).toBe(H + i + 1);
      }

      // The single most important long-run property: nothing ever broke.
      expect(r.value.violations).toEqual([]);
    });

    it(`keeps every committed Kura finite and bounded over ${hours} hours`, { timeout: LONG }, () => {
      const r = longRun(hours);
      expect(r.ok).toBe(true);
      if (!r.ok) return;

      for (const s of r.value.snapshots) {
        for (const song of [...s.active, ...s.vaulted]) {
          expect(Number.isFinite(song.persistentKura), `hour ${s.hour}`).toBe(true);
          expect(song.persistentKura).toBeGreaterThanOrEqual(0);
          expect(Number.isFinite(song.boraScore), `hour ${s.hour}`).toBe(true);
          expect(Number.isFinite(song.activeC), `hour ${s.hour}`).toBe(true);
        }
      }
    });

    it(`replays identically over ${hours} hours`, { timeout: LONG }, () => {
      const a = longRun(hours);
      const b = longRun(hours);
      expect(a.ok && b.ok).toBe(true);
      if (!a.ok || !b.ok) return;
      expect(fingerprintText(a.value)).toBe(fingerprintText(b.value));
    });
  }

  it('survives 10 000 hours with no drift or failure', { timeout: VERY_LONG }, () => {
    const r = longRun(10_000);
    expect(r.ok).toBe(true);
    if (!r.ok) return;

    expect(r.value.snapshots).toHaveLength(10_000);
    expect(r.value.violations).toEqual([]);

    // No accumulation pathology: the Kura pool stays finite.
    expect(Number.isFinite(r.value.metrics.finalTotalPersistentKura)).toBe(true);
    expect(r.value.metrics.peakPersistentKura).toBeGreaterThanOrEqual(0);

    // Active C per hour is bounded by the WINDOW, not by the runway: at most
    // 72 active hours × C_MAX each, summed across the whole population. The
    // bound is derived from the observed population size, so it stays honest.
    const activeSongCount = r.value.snapshots[r.value.snapshots.length - 1].active.length;
    const windowCeiling = activeSongCount * 72 * 2;
    const maxActiveC = Math.max(...r.value.snapshots.map((s) => s.totalActiveC));
    expect(Number.isFinite(maxActiveC)).toBe(true);
    expect(maxActiveC).toBeLessThanOrEqual(windowCeiling);
  });

  it('keeps the population alive and the chart populated throughout', { timeout: LONG }, () => {
    const r = longRun(1000);
    expect(r.ok).toBe(true);
    if (!r.ok) return;
    const withActivity = r.value.snapshots.filter((s) => s.totalActiveC > 0).length;
    expect(withActivity).toBeGreaterThan(900);
  });

  it('keeps the 168-hour reference scenario clean', () => {
    const r = runSimulation(scenarioJLongRun(168));
    expect(r.ok).toBe(true);
    if (r.ok) expect(r.value.violations).toEqual([]);
  });
});